}

fn set_app_id(&mut self, app_id: &str) {
    let mut state = self.borrow_mut();
    if let Some(toplevel) = state.surface_state.toplevel() {
        toplevel.set_app_id(app_id.to_owned());
    }
    state.app_id = Some(app_id.to_owned());
}

