fn zoom(&self) {
    let state = self.borrow();
    if let Some(toplevel) = state.surface_state.toplevel() {
        if !state.maximized {
            toplevel.set_maximized();
        } else {
            toplevel.unset_maximized();
        }
    }
}

fn toggle_fullscreen(&self) {
    let state = self.borrow();
    if let Some(toplevel) = state.surface_state.toplevel() {
        if !state.fullscreen {
            toplevel.set_fullscreen(None);
        } else {
            toplevel.unset_fullscreen();
        }
    }
}

