            false,
            self.x_window,
            state.atoms._NET_WM_STATE,
            xproto::AtomEnum::ATOM,
            0,
            u32::MAX,
        ),
    )?;

    let atoms = reply
        .value
        .chunks_exact(4)
        .map(|chunk| u32::from_ne_bytes([chunk[0], chunk[1], chunk[2], chunk[3]]));

